input.find:
export function parseRange(text) {
  const [from, to] = text.split("-");
  return { from: Number(from), to: Number(to) };
}

input.replace:
export function parseRange(text) {
  const parts = text.split("-");
  const from = Number(parts[0]);
  const to = parts.length === 1 ? from : Number(parts[1]);
  return { from, to };
}
